const incoming = $input.first().json;
const candidate = incoming && incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const body = candidate && typeof candidate === 'object' && !Array.isArray(candidate) ? candidate : {};
const clean = value => typeof value === 'string' ? value.trim() : '';
const lead = {
  name: clean(body.name),
  email: clean(body.email).toLowerCase(),
  company: clean(body.company),
  website: clean(body.website),
  role: clean(body.role),
  need: clean(body.need),
  budget: clean(body.budget),
  source: clean(body.source) || 'webhook'
};
const errors = [];
const limits = { name: 120, email: 254, company: 200, website: 2048, role: 160, need: 2000, budget: 160, source: 120 };
for (const key of ['name', 'email', 'company', 'need']) {
  if (!lead[key]) errors.push(key + ' is required');
}
for (const [key, limit] of Object.entries(limits)) {
  if (lead[key].length > limit) errors.push(key + ' must be at most ' + limit + ' characters');
}
if (lead.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) {
  errors.push('email must be a valid email address');
}
if (lead.website) {
  try {
    const normalizedWebsite = new URL(lead.website.startsWith('http://') || lead.website.startsWith('https://') ? lead.website : 'https://' + lead.website);
    if (!['http:', 'https:'].includes(normalizedWebsite.protocol)) errors.push('website must use HTTP or HTTPS');
    lead.website = normalizedWebsite.href;
  } catch {
    errors.push('website must be a valid URL');
  }
}
return [{
  json: {
    ...lead,
    isValid: errors.length === 0,
    validationError: errors.join('; '),
    receivedAt: new Date().toISOString()
  }
}];

const response = $input.first().json;
const text = response.choices?.[0]?.message?.content;
if (typeof text !== 'string' || !text.trim()) {
  throw new Error('OpenAI returned no message content; check the credential, model access, and API response.');
}
let ai;
try {
  ai = JSON.parse(text);
} catch {
  throw new Error('OpenAI response was not valid JSON.');
}
const componentRanges = {
  need_clarity_score: 35,
  role_fit_score: 25,
  buying_intent_score: 25,
  budget_timing_score: 15
};
for (const [key, max] of Object.entries(componentRanges)) {
  if (!Number.isInteger(ai[key]) || ai[key] < 0 || ai[key] > max) {
    throw new Error('AI response has invalid ' + key + '; expected integer 0-' + max + '.');
  }
}
const l = $('Normalize and Validate Lead').first().json;
const score = ai.need_clarity_score + ai.role_fit_score + ai.buying_intent_score + ai.budget_timing_score;
const qualification = score >= 75 ? 'high' : score >= 45 ? 'medium' : 'low';
const cleanList = value => Array.isArray(value) ? value.filter(v => typeof v === 'string').map(v => v.trim()).filter(Boolean).slice(0, 4) : [];
const cleanText = value => typeof value === 'string' ? value.trim().slice(0, 1200) : '';
return [{
  json: {
    success: true,
    lead: {
      name: l.name, email: l.email, company: l.company, website: l.website,
      role: l.role, need: l.need, budget: l.budget, source: l.source
    },
    qualification: {
      lead_score: score,
      components: {
        need_clarity_score: ai.need_clarity_score,
        role_fit_score: ai.role_fit_score,
        buying_intent_score: ai.buying_intent_score,
        budget_timing_score: ai.budget_timing_score
      },
      qualification,
      fit_reasons: cleanList(ai.fit_reasons),
      risks: cleanList(ai.risks),
      recommended_next_step: cleanText(ai.recommended_next_step),
      personalized_opening_line: cleanText(ai.personalized_opening_line),
      summary: cleanText(ai.summary),
      confidence_note: cleanText(ai.confidence_note)
    },
    receivedAt: l.receivedAt,
    processedAt: new Date().toISOString()
  }
}];
